def _dump(node):
    return ast.dump(node, include_attributes=False)


def _function(tree, name):
    found = [node for node in tree.body if type(node) is ast.FunctionDef and node.name == name]
    if len(found) != 1:
        raise Boundary('one complete intro IRQ source function required: ' + name)
    return found[0]


def _code_shape(code):
    return tuple(getattr(code, name) for name in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value for value in code.co_consts),)


def _top_code(code, name):
    found = [value for value in code.co_consts if type(value) is CodeType
        and value.co_name == name and value.co_qualname == name]
    if len(found) != 1:
        raise Boundary('one full module-context intro IRQ CodeType required: ' + name)
    return found[0]


def _lift_intro_tree(original):
    result = copy.deepcopy(original)
    name = 'lowbank_coordinate_live_state_61_fields'
    function = _function(original, name)
    for owner in NAMES:
        if _dump(_function(original, owner)) != _dump(ast.parse(EXPECTED_SOURCES[owner]).body[0]):
            raise Boundary('complete reviewed intro IRQ source differs: ' + owner)
    before = ast.parse('_lowbank_ui_known_child_fields(state,frame,0x206)', mode='eval').body
    after = ast.parse('_intro_reset_jump(state,frame,0x4786,0x206)', mode='eval').body
    hits = []

    class Lift(ast.NodeTransformer):
        def visit_Call(self, node):
            if _dump(node) == _dump(before):
                hits.append(node)
                return ast.copy_location(copy.deepcopy(after), node)
            return self.generic_visit(node)

    changed = Lift().visit(copy.deepcopy(function))
    if len(hits) != 1:
        raise Boundary('one exact original4786 nonreturning jump expression required')
    undone = []

    class Inverse(ast.NodeTransformer):
        def visit_Call(self, node):
            if _dump(node) == _dump(after):
                undone.append(node)
                return ast.copy_location(copy.deepcopy(before), node)
            return self.generic_visit(node)

    inverse = Inverse().visit(copy.deepcopy(changed))
    if len(undone) != 1 or _dump(inverse) != _dump(function):
        raise Boundary('whole4742 JMP expression inverse differs')
    index = original.body.index(function)
    result.body[index] = changed
    restored = copy.deepcopy(result)
    restored.body[index] = inverse
    if _dump(restored) != _dump(original):
        raise Boundary('entire Lowbank IRQ module inverse differs')
    return ast.fix_missing_locations(result)


class OriginalIntroResetJump(Exception):
    """A real JMP control transfer: no CALL slot, RTE result or ordinary return."""
    def __init__(self, owner, frame, full_sr):
        self.owner, self.state, self.frame = owner, owner.state, frame
        self.source_pc, self.target, self.full_sr = 0x4786, 0x206, full_sr
        super().__init__('original4786 JMP206 discarded the old IRQ/Main continuation')


class IntroIrqPrograms:
    """Explicit per-Scene provider for the complete actual original IRQ core."""
    def __init__(self, state):
        self.state = checked_state(state)
        self.thread, self.active, self.pending = threading.get_ident(), False, None
        self.entered = None
        self.jumps = self.claimed = 0
        tree = ast.parse(inspect.getsource(lowbank), filename=lowbank.__file__)
        plain = compile(tree, lowbank.__file__, 'exec', dont_inherit=True)
        derived = compile(_lift_intro_tree(tree), lowbank.__file__, 'exec', dont_inherit=True)
        self.originals = {}
        namespace = dict(vars(lowbank))
        if '_intro_reset_jump' in namespace:
            raise Boundary('private intro JMP name must not shadow original source')
        namespace['_intro_reset_jump'] = self._jump
        self.views = {}
        for name in NAMES:
            original = getattr(lowbank, name)
            if (type(original) is not FunctionType or original.__globals__ is not vars(lowbank)
                    or original.__closure__ is not None or original.__module__ != lowbank.__name__
                    or _code_shape(original.__code__) != _code_shape(_top_code(plain, name))):
                raise Boundary('actual complete original intro function/source identity required: ' + name)
            self.originals[name] = (original, original.__code__)
            view = FunctionType(_top_code(derived, name), namespace, name, original.__defaults__, None)
            view.__kwdefaults__ = original.__kwdefaults__
            view.__annotations__ = dict(original.__annotations__)
            self.views[name] = namespace[name] = view
        self.source_contract = dict(confidence='confirmed_complete_source_inverses_runtime_unverified',
            whole_functions=5, changed_original_expressions=1, whole_FN_inverse=True,
            whole_module_inverse=True, module_monkeypatch=False, PC_interpreter=False,
            real_jump=[0x4786, 0x206], ordinary_RTS_or_RTE_invented=False)

    def _guard(self):
        if threading.get_ident() != self.thread:
            raise Boundary('intro IRQ provider belongs to its actual Scene thread')
        for name, (owner, code) in self.originals.items():
            if getattr(lowbank, name) is not owner or owner.__code__ is not code:
                raise Boundary('actual complete intro IRQ callee was rebound: ' + name)

    def run_irq(self, entered):
        self._guard()
        entered = _movement_frame(self.state, entered)
        if self.active or self.pending is not None or entered.status != self.state.sr & 31:
            raise Boundary('one actual same-Scene IRQ invocation and no unclaimed JMP required')
        if not self.state.events or self.state.events[-1][:4] != ('interrupt_enter', 6, 0x78, 0x481E):
            raise Boundary('actual original level6 exception entry must immediately precede this core')
        self.active, self.entered = True, entered
        try:
            return self.views['lowbank_process_device_control_6_fields'](self.state, entered)
        finally:
            self.active, self.entered = False, None

    def _jump(self, state, frame, source_pc, target):
        self._guard()
        frame = _movement_frame(state, frame)
        if (not self.active or state is not self.state or self.pending is not None
                or (source_pc, target) != (0x4786, 0x206)
                or frame.status != state.sr & 31
                or frame.stack_cursor.base != self.entered.stack_cursor.base - 68):
            raise Boundary('actual4742 terminal JMP with original MOVEM/two child slots required')
        jump = OriginalIntroResetJump(self, frame, state.sr)
        self.pending = jump
        self.jumps += 1
        state.events.append(('original_nonreturning_jump', 0x4786, 0x206,
            frame.stack_cursor.base, state.sr))
        raise jump

    def claim(self, jump):
        self._guard()
        if (type(jump) is not OriginalIntroResetJump or jump is not self.pending
                or jump.owner is not self or self.active or jump.state is not self.state
                or jump.full_sr != self.state.sr or jump.frame.status != self.state.sr & 31):
            raise Boundary('one unconsumed actual original4786 transfer required')
        self.pending = None
        self.claimed += 1
        return jump.frame


def bind_intro_irq(runtime, programs):
    """Explicit instance dependency injection, never a replaced method/global."""
    from ..high_level_video.frame_interrupts import OriginalInterruptRuntime
    if (type(runtime) is not OriginalInterruptRuntime or type(programs) is not IntroIrqPrograms
            or runtime.state is not programs.state or runtime._active
            or getattr(runtime, '_intro_reset_owner', None) not in (None, programs)):
        raise Boundary('one inactive actual IRQ runtime and same-Scene exact intro provider required')
    programs._guard()
    runtime._intro_reset_owner = programs


def run_original_or_intro_irq(runtime, state, entered, original):
    """Old default is unchanged; only an explicitly bound provider participates."""
    owner = getattr(runtime, '_intro_reset_owner', None)
    if owner is None:
        return original(state, entered)
    if (type(owner) is not IntroIrqPrograms or state is not owner.state
            or runtime.state is not state or not runtime._active
            or original is not owner.originals['lowbank_process_device_control_6_fields'][0]):
        raise Boundary('actual same-Scene intro IRQ provider/original callee required')
    return owner.run_irq(entered)
